#include <vector>
#include <cmath>
using namespace std;

class Solution {
public:
    vector<int> bestCoordinate(vector<vector<int>>& towers, int radius) {
        int max_q = 0;
        vector<int> best = {0, 0};
        for (int x = 0; x <= 50; ++x) {
            for (int y = 0; y <= 50; ++y) {
                int quality = 0;
                for (const auto& t : towers) {
                    double d = hypot(x - t[0], y - t[1]);
                    if (d <= radius) {
                        quality += floor(t[2] / (1.0 + d));
                    }
                }
                if (quality > max_q) {
                    max_q = quality;
                    best = {x, y};
                }
            }
        }
        return best;
    }
};

class Solution {
    public int[] bestCoordinate(int[][] towers, int radius) {
        int maxQ = 0;
        int[] best = new int[]{0, 0};
        for (int x = 0; x <= 50; ++x) {
            for (int y = 0; y <= 50; ++y) {
                int quality = 0;
                for (int[] t : towers) {
                    double d = Math.hypot(x - t[0], y - t[1]);
                    if (d <= radius) {
                        quality += (int)Math.floor(t[2] / (1.0 + d));
                    }
                }
                if (quality > maxQ) {
                    maxQ = quality;
                    best[0] = x;
                    best[1] = y;
                }
            }
        }
        return best;
    }
}

